from collections import deque

def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    # Build Aho-Corasick automaton
    trie = [{}]
    bad = [False]

    for word in banned:
        node = 0
        for ch in word:
            if ch not in trie[node]:
                trie[node][ch] = len(trie)
                trie.append({})
                bad.append(False)
            node = trie[node][ch]
        bad[node] = True

    num_nodes = len(trie)
    fail = [0] * num_nodes
    go = [{ch: 0 for ch in alphabet} for _ in range(num_nodes)]

    q = deque()
    for ch in alphabet:
        if ch in trie[0]:
            nxt = trie[0][ch]
            go[0][ch] = nxt
            q.append(nxt)
        else:
            go[0][ch] = 0

    while q:
        u = q.popleft()
        bad[u] = bad[u] or bad[fail[u]]
        for ch in alphabet:
            if ch in trie[u]:
                v = trie[u][ch]
                fail[v] = go[fail[u]][ch]
                go[u][ch] = v
                q.append(v)
            else:
                go[u][ch] = go[fail[u]][ch]

    if bad[0]:
        return 0

    valid_nodes = [i for i in range(num_nodes) if not bad[i]]
    idx_map = {node: idx for idx, node in enumerate(valid_nodes)}
    m = len(valid_nodes)

    # Transition matrix M[i][j] = ways from state i to state j in 1 step
    M = [[0] * m for _ in range(m)]
    for u in valid_nodes:
        i = idx_map[u]
        for ch in alphabet:
            v = go[u][ch]
            if not bad[v]:
                M[i][idx_map[v]] += 1

    def mat_mul(A, B):
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            Ai = A[i]
            resi = res[i]
            for k in range(m):
                a_ik = Ai[k]
                if a_ik:
                    Bk = B[k]
                    for j in range(m):
                        resi[j] = (resi[j] + a_ik * Bk[j]) % MOD
        return res

    # Matrix exponentiation: M^n
    res = [[int(i == j) for j in range(m)] for i in range(m)]
    base = M
    exp = n
    while exp > 0:
        if exp & 1:
            res = mat_mul(res, base)
        base = mat_mul(base, base)
        exp >>= 1

    start_idx = idx_map[0]
    return sum(res[start_idx]) % MOD
